INSERT INTO academic_schedule
		(
			schedule_no
			, class_id
			, notice_no
			, schedule_writer
			, schedule_category
			, schedule_title
			, start_date
			, end_date
		)
		VALUES
		(
			#{ scheduleNo}

			, #{classId}
			, #{noticeNo}
			, #{scheduleWriter}
			, #{scheduleCategory}
			, #{scheduleTitle}
			, #{startDate}
			, #{endDate}
		)
